<template>
  <section class="workspace-view">
    <div class="workbench-head"><div><h2>{{ tx.title }}</h2><p>{{ tx.subtitle }}</p></div><button class="refresh" :disabled="loading" @click="load">↻ {{ tx.refresh }}</button></div>
    <div class="review-layout">
      <aside class="panel queue-panel">
        <div class="queue-head"><span>{{ tx.queue }}</span><b>{{ pendingTasks.length }}</b></div>
        <button v-for="task in pendingTasks" :key="task.task_id" :class="['queue-item',{selected:selected?.task_id===task.task_id}]" @click="selected=task;notice=''">
          <div><strong>{{ task.request.task_name }}</strong><small>{{ task.request.workshop_id }} · {{ task.request.production_date }}</small></div>
          <span class="mono">V{{ task.version }}</span>
          <p><b>{{ formatNumber(locale, task.plan?.summary.planned_quantity || 0) }}</b> PCS · {{ task.request.orders.length }} {{ tx.orders }}</p>
          <time>{{ formatDateTime(locale, task.updated_at) }}</time>
        </button>
        <div v-if="!loading && !pendingTasks.length" class="empty"><b>✓</b><span>{{ tx.empty }}</span></div>
      </aside>

      <article class="panel approval-panel">
        <template v-if="selected">
          <div class="approval-head"><div><h3>{{ selected.request.task_name }}</h3><small class="mono">{{ selected.task_id }} · {{ selected.trace_id }}</small></div><span>{{ statusText(locale, selected.status) }}</span></div>
          <div class="facts"><div><span>{{ tx.quantity }}</span><b>{{ formatNumber(locale, selected.plan?.summary.planned_quantity || 0) }}</b></div><div><span>{{ tx.finish }}</span><b>{{ finishTime }}</b></div><div><span>{{ tx.load }}</span><b>{{ Math.round((selected.plan?.summary.average_utilization || 0)*100) }}%</b></div><div><span>{{ tx.devices }}</span><b>{{ selected.plan?.summary.device_count || 0 }}</b></div></div>

          <section class="approval-section"><h4>{{ tx.risks }}</h4><div class="risk-row" v-for="risk in selected.plan?.risks || []" :key="risk.code"><span :class="risk.level">{{ risk.code }}</span><div><b>{{ riskCopy(risk.code, 'message', risk.message) }}</b><small>{{ riskCopy(risk.code, 'mitigation', risk.mitigation) }}</small></div></div></section>
          <section class="approval-section"><h4>{{ tx.keyAssignments }}</h4><div class="assignment-head"><span>{{ tx.order }}</span><span>{{ tx.process }}</span><span>{{ tx.station }}</span><span>{{ tx.team }}</span><span>{{ tx.time }}</span></div><div class="assignment-row" v-for="item in selected.plan?.assignments || []" :key="item.assignment_id"><span>{{ item.order_id }}</span><span>{{ processName(item.process) }}</span><span>{{ item.station_code }}</span><span>{{ teamName(item.team_name) }}</span><span class="mono">{{ clockTime(item.start_at) }}–{{ clockTime(item.end_at) }}</span></div></section>
          <section class="approval-section"><h4>{{ tx.comment }}</h4><textarea v-model="comment" :placeholder="tx.placeholder" rows="3"></textarea></section>
          <div class="decision-bar"><div><span>{{ tx.policy }}</span><small>{{ tx.policyNote }}</small></div><button class="reject" :disabled="submitting || selected.status!=='need_review'" @click="submit('reject')">{{ tx.reject }}</button><button class="approve" :disabled="submitting || selected.status!=='need_review'" @click="submit('approve')">{{ tx.approve }} →</button></div>
          <p v-if="notice" :class="['notice',selected.status]">{{ notice }}</p>
        </template>
        <div v-else class="empty main-empty"><b>✓</b><span>{{ tx.select }}</span></div>
      </article>
    </div>
    <p v-if="error" class="error-line">{{ error }}</p>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { getTask, listTasks, reviewTask } from '../services/api'
import type { TaskSnapshot } from '../types'
import { formatDateTime, formatNumber, statusText, type Locale } from '../utils/workbench'

const props=defineProps<{locale:Locale;initialTaskId?:string}>()
const emit=defineEmits<{(event:'reviewed',task:TaskSnapshot):void}>()
const tasks=ref<TaskSnapshot[]>([]),selected=ref<TaskSnapshot|null>(null),loading=ref(false),submitting=ref(false),error=ref(''),notice=ref(''),comment=ref('')
const copy={
  'zh-TW':{title:'審核中心',subtitle:'集中處理待覆核計畫，核准後才允許下發製造執行系統。',refresh:'重新整理',queue:'待辦佇列',orders:'張工單',empty:'目前沒有待審核計畫',quantity:'計畫數量',finish:'預計完成',load:'平均負載',devices:'使用設備',risks:'風險與處置',keyAssignments:'工位分配明細',order:'工單',process:'製程',station:'工位',team:'班組',time:'時段',comment:'審核意見',placeholder:'記錄核准條件、現場調整或退回原因',policy:'下發策略',policyNote:'人工核准 · 版本鎖定 · 可追溯',reject:'退回計畫',approve:'核准並下發',select:'從左側選擇待辦計畫',approved:'審核已完成，計畫已送交 MES 介面。',rejected:'計畫已退回，未觸發 MES 下發。'},
  'zh-CN':{title:'审核中心',subtitle:'集中处理待复核计划，批准后才允许下发制造执行系统。',refresh:'刷新',queue:'待办队列',orders:'张工单',empty:'当前没有待审核计划',quantity:'计划数量',finish:'预计完成',load:'平均负载',devices:'使用设备',risks:'风险与处置',keyAssignments:'工位分配明细',order:'工单',process:'工序',station:'工位',team:'班组',time:'时段',comment:'审核意见',placeholder:'记录批准条件、现场调整或退回原因',policy:'下发策略',policyNote:'人工批准 · 版本锁定 · 可追溯',reject:'退回计划',approve:'批准并下发',select:'从左侧选择待办计划',approved:'审核已完成，计划已送交 MES 接口。',rejected:'计划已退回，未触发 MES 下发。'},
  'en-US':{title:'Review center',subtitle:'Process pending plans centrally. MES release requires supervisor approval.',refresh:'Refresh',queue:'Pending queue',orders:'orders',empty:'No plans are awaiting review',quantity:'Planned quantity',finish:'Estimated finish',load:'Average load',devices:'Equipment used',risks:'Risks and actions',keyAssignments:'Station assignments',order:'Order',process:'Process',station:'Station',team:'Team',time:'Window',comment:'Review note',placeholder:'Record conditions, floor adjustments or rejection reason',policy:'Release policy',policyNote:'Human approval · Version lock · Traceable',reject:'Return plan',approve:'Approve & publish',select:'Select a pending plan from the queue',approved:'Review completed and the plan was sent to the MES interface.',rejected:'Plan returned; MES release was not triggered.'},
}
const tx=computed(()=>copy[props.locale]),pendingTasks=computed(()=>tasks.value.filter(t=>t.status==='need_review'))
const finishTime=computed(()=>selected.value?.plan?.summary.estimated_completion_at?formatDateTime(props.locale,selected.value.plan.summary.estimated_completion_at):'--')
function clockTime(v:string){return new Date(v).toLocaleTimeString(props.locale,{hour:'2-digit',minute:'2-digit',hour12:false})}
function processName(v:string){if(props.locale==='en-US')return v==='组装'?'Assembly':v==='测试'?'Test':'Packaging';return props.locale==='zh-TW'?v.replace('组','組').replace('测试','測試').replace('包装','包裝'):v}
function teamName(v:string){return props.locale==='en-US'?(v==='甲班'?'Team A':v==='乙班'?'Team B':v):v}
function riskCopy(code:string,field:'message'|'mitigation',fallback:string){const table:Record<string,Record<Locale,[string,string]>>={CAPACITY_OVERLOAD:{'zh-TW':['至少一個工位超過單班額定產能','拆分批次至夜班或啟用跨線生產'],'zh-CN':['至少一个工位超过单班额定产能','拆分批次到夜班或启用跨线生产'],'en-US':['At least one station exceeds rated shift capacity','Split the lot or enable cross-line production']},ATTENDANCE_LOW:{'zh-TW':['夜班到崗率低於 90%','預留多能工並於班前確認到崗'],'zh-CN':['夜班到岗率低于 90%','预留多能工并在班前确认到岗'],'en-US':['Night-shift attendance is below 90%','Reserve multi-skilled operators and confirm attendance']},DATA_DEGRADED:{'zh-TW':['部分業務資料不可用','確認基線資源後再下發'],'zh-CN':['部分业务数据不可用','确认基线资源后再下发'],'en-US':['Some business data is unavailable','Verify baseline resources before release']},NORMAL:{'zh-TW':['資源與交期約束位於安全區間','依標準班前點檢執行'],'zh-CN':['资源与交期约束位于安全区间','按标准班前点检执行'],'en-US':['Resources and due dates are within the safe range','Run the standard pre-shift inspection']}};return table[code]?.[props.locale]?.[field==='message'?0:1]||fallback}
async function load(){loading.value=true;error.value='';try{tasks.value=await listTasks();if(props.initialTaskId){const target=await getTask(props.initialTaskId);selected.value=target.status==='need_review'?target:pendingTasks.value[0]||null}else selected.value=pendingTasks.value[0]||null}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function submit(action:'approve'|'reject'){if(!selected.value)return;submitting.value=true;error.value='';try{const updated=await reviewTask(selected.value.task_id,action,selected.value.version,comment.value);selected.value=updated;tasks.value=tasks.value.map(t=>t.task_id===updated.task_id?updated:t);notice.value=action==='approve'?tx.value.approved:tx.value.rejected;emit('reviewed',updated)}catch(e:any){error.value=e.message}finally{submitting.value=false}}
onMounted(load)
</script>

<style scoped>
