-size:9px;color:var(--muted)}.facts b{font:600 17px "Bahnschrift";margin-top:5px}.approval-section{padding:14px 0;border-top:1px solid rgba(38,52,58,.75)}.approval-section h4{font-size:10px;color:var(--muted);margin:0 0 10px}.risk-row{display:grid;grid-template-columns:125px 1fr;gap:10px;padding:9px;background:#10191d;margin-bottom:6px}.risk-row>span{font:8px "Cascadia Mono";color:var(--safety)}.risk-row>span.high{color:var(--oxide)}.risk-row b,.risk-row small{display:block}.risk-row b{font-size:10px}.risk-row small{font-size:9px;color:var(--muted);margin-top:4px}.assignment-head,.assignment-row{display:grid;grid-template-columns:1.3fr .7fr .8fr .65fr .9fr;gap:8px;padding:7px 8px}.assignment-head{font-size:8px;color:#617177}.assignment-row{font-size:9px;border-top:1px solid rgba(38,52,58,.55)}textarea{width:100%;background:#0e171b;border:1px solid var(--steel);color:var(--paper);padding:10px;resize:vertical}.decision-bar{display:grid;grid-template-columns:1fr auto auto;gap:9px;align-items:center;padding-top:14px;border-top:1px solid var(--steel)}.decision-bar>div span,.decision-bar>div small{display:block}.decision-bar>div span{font-size:10px}.decision-bar>div small{font-size:8px;color:var(--muted);margin-top:3px}.decision-bar button{padding:11px 15px;border:1px solid var(--steel);background:transparent;color:var(--muted)}.decision-bar .approve{background:var(--coolant);color:#071115;border-color:var(--coolant);font-weight:700}.decision-bar button:disabled{opacity:.35}.notice{padding:10px;font-size:10px;color:var(--ok);background:rgba(117,198,154,.08)}.notice.rejected{color:#ef896e;background:rgba(197,90,61,.08)}.empty{padding:50px 10px;display:grid;place-items:center;gap:8px;color:#68777b;font-size:10px}.empty b{font-size:24px;color:var(--ok)}.main-empty{padding-top:170px}.error-line{color:#ef896e;font-size:10px}@media(max-width:900px){.review-layout{grid-template-columns:1fr}.queue-panel{max-height:300px;overflow:auto}.facts{grid-template-columns:1fr 1fr}.assignment-head,.assignment-row{min-width:650px}.approval-section{overflow:auto}}
</style>
